std::vec2 ac = c - a;
std::vec2 ap = p - a;
float det = ab.x * ac.y - ac.x * ab.y;
if (std::abs(det) < 1e-6) return std::vec3(-1, 1, 1);
float invDet = 1.0f / det;
float beta = (ap.x * ac.y - ap.y * ac.x) * invDet;
float gamma = (ap.y * ab.x - ap.x * ab.y) * invDet;
float alpha = 1.0f - beta - gamma;
return std::vec3(alpha, beta, gamma);

